#!/usr/bin/env python3
"""Emit a wave workflow script for a set of lane groups, skipping slugs that
already have a non-empty requirement patch."""
import json, os, sys

SPEC = json.load(open('/workspace/agent_plans/lanes.json'))
TEMPLATE = open('/workspace/agent_plans/impl_wave_template.js').read()
PATCHDIR = '/workspace/requirement_patches'

GROUPS = {
    # hdfs + hadoop-common + native
    'A': lambda n: n.startswith(('HDFS_', 'RBF_', 'LIBHDFS', 'NATIVE_', 'COMMON_')),
    # yarn + mapreduce + tools + docs + ci + poms
    'B': lambda n: n.startswith(('YARN_', 'MR', 'S3A', 'ABFS', 'OSS', 'DISTCP', 'DOCS', 'CI_DEV', 'POM')),
    # broad conflict-prone sweeps, run last
    'C': lambda n: n.startswith(('GUAVA_', 'SWEEP_', 'ENFORCER')),
}

def done(slug):
    p = os.path.join(PATCHDIR, slug + '.diff')
    return os.path.exists(p) and os.path.getsize(p) > 0

def build(group, only=None):
    pred = GROUPS[group]
    lanes = []
    for name, slugs in SPEC['lanes'].items():
        if only is not None:
            if name not in only:
                continue
        elif not pred(name):
            continue
        remaining = [s for s in slugs if not done(s)]
        if remaining:
            lanes.append(remaining)
    wave = {'lanes': lanes, 'light': SPEC['light']}
    js = TEMPLATE.replace('/*__WAVE__*/', json.dumps(wave))
    path = f'/workspace/agent_plans/wave_{group}.js'
    open(path, 'w').write(js)
    print(f'wave {group}: {len(lanes)} lanes, {sum(len(l) for l in lanes)} reqs -> {path}')

if __name__ == '__main__':
    for g in sys.argv[1:] or ['A', 'B', 'C']:
        build(g)

