import sys, os, subprocess, json

def strip_java(src):
    out = []
    i, n = 0, len(src)
    state = 'code'
    while i < n:
        c = src[i]
        nxt = src[i+1] if i + 1 < n else ''
        if state == 'code':
            if c == '/' and nxt == '/':
                state = 'line'; i += 2; continue
            if c == '/' and nxt == '*':
                state = 'block'; i += 2; continue
            if c == '"':
                if src[i:i+3] == '"""':
                    state = 'text'; i += 3; continue
                state = 'str'; i += 1; out.append(' '); continue
            if c == "'":
                state = 'chr'; i += 1; out.append(' '); continue
            out.append(c); i += 1; continue
        if state == 'line':
            if c == '\n':
                state = 'code'; out.append('\n')
            i += 1; continue
        if state == 'block':
            if c == '*' and nxt == '/':
                state = 'code'; i += 2; continue
            if c == '\n':
                out.append('\n')
            i += 1; continue
        if state == 'text':
            if src[i:i+3] == '"""':
                state = 'code'; i += 3; continue
            if c == '\n':
