export const meta = {
  name: 'hadoop-requirements-verify',
  description: 'Adversarially verify each implemented requirement and repair gaps in place',
  phases: [
    { title: 'Verify' },
  ],
}

const WAVE = /*__WAVE__*/
const lanes = WAVE.lanes

function promptFor(slug) {
  return `You are auditing ONE already-implemented requirement in the Apache Hadoop tree at /workspace, and repairing it if it is wrong or incomplete.

REQUIREMENT SLUG: ${slug}
REQUIREMENT FILE: /workspace/requirements/${slug}.yaml
The change that was made for it: \`git -C /workspace log --oneline --all --grep "impl: ${slug}"\` then \`git show <sha>\`, and/or /workspace/requirement_patches/${slug}.diff

Be adversarial. Your default assumption is that the previous agent got something subtly wrong. Check, in this order:

1. COMPILABILITY (highest value - there is no full build gate for every module). For every file the patch touched, re-read the CURRENT file content (not just the diff) and confirm:
   - every type / method / field / constant referenced actually exists with that exact signature (grep the declaring class),
   - every needed import is present and no import is unused-but-newly-added,
   - generics, checked exceptions (\`throws\`), \`final\`, static vs instance usage, and interface implementations all line up (if a method was added to an interface, EVERY implementor must implement it),
   - braces/parens balance and no duplicated or orphaned code fragments were left behind,
   - test code compiles too (assert imports, JUnit 4 vs 5 mixing, LambdaTestUtils/GenericTestUtils helpers that actually exist in this version).
2. FAITHFULNESS to the requirement's acceptance signals. Every bullet in "Desired outcome" and "Acceptance signals" must actually hold. Names must match the requirement text verbatim (classes, methods, config keys, metric names, JSON field names, log wording). Hidden tests from the real upstream Apache commit grade this.
3. COMPLETENESS of the plumbing: new config key -> also in the matching *-default.xml and the module's config-constants class; new metric -> registered and readable through the same mechanism its neighbours use; new REST/RPC method -> added to every interface/protocol/impl/mock that the compiler will require; new public API -> annotated like its neighbours.
4. SCOPE: the change must not have broken or gratuitously rewritten unrelated behaviour.

IF EVERYTHING IS CORRECT: change nothing.

IF YOU FIND A PROBLEM: fix it minimally, then commit the repair yourself with exactly this shape (real paths, keep the flock, note the APPEND \`>>\` so the original patch content is preserved):

  cd /workspace && flock /tmp/hadoop-git.lock bash -c 'git add -A -- PATH1 PATH2 ... && git diff --cached --binary >> requirement_patches/${slug}.diff && git commit -q -m "fix: ${slug}" && git log --oneline -1'

FORBIDDEN: git checkout/switch/stash/reset/revert/clean/rebase/merge/cherry-pick, \`git add\` without an explicit pathspec, \`git commit --amend\`, \`mvn\`, and touching requirement_patches/ entries for other slugs. ~380 other requirements live in this same tree; other agents may be working in it right now.

Return ONLY this JSON object:
{"slug":"${slug}","verdict":"ok"|"fixed"|"broken","issues":["short description of each real problem found"],"repaired":true|false,"files":["files you changed, if any"],"notes":"anything the orchestrator must know"}`
}

const SCHEMA = {
  type: 'object',
  properties: {
    slug: { type: 'string' },
    verdict: { type: 'string' },
    issues: { type: 'array', items: { type: 'string' } },
    repaired: { type: 'boolean' },
    files: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
  required: ['slug', 'verdict'],
  additionalProperties: true,
}

phase('Verify')
log(`${lanes.length} lanes, ${lanes.reduce((a, l) => a + l.length, 0)} requirements to audit`)

const results = await parallel(lanes.map((lane) => async () => {
  const out = []
  for (const slug of lane) {
    let r = null
    try {
      r = await agent(promptFor(slug), { label: `verify:${slug}`, phase: 'Verify', schema: SCHEMA })
    } catch (e) {
      r = { slug, verdict: 'broken', issues: [`agent error: ${String(e).slice(0, 200)}`] }
    }
    out.push(r || { slug, verdict: 'broken', issues: ['agent returned null'] })
  }
  return out
}))

const flat = results.filter(Boolean).flat().filter(Boolean)
return {
  total: flat.length,
  ok: flat.filter((r) => r.verdict === 'ok').length,
  fixed: flat.filter((r) => r.verdict === 'fixed').length,
  broken: flat.filter((r) => r.verdict === 'broken').map((r) => ({ slug: r.slug, issues: r.issues, notes: r.notes })),
  fixedDetail: flat.filter((r) => r.verdict === 'fixed').map((r) => ({ slug: r.slug, issues: r.issues })),
}

