export const meta = {
  name: 'hadoop-sweep-wave',
  description: 'Implement the broad cross-cutting cleanup requirements (guava removal, unused imports, enforcer rules)',
  phases: [
    { title: 'Sweep' },
  ],
}

const WAVE = /*__WAVE__*/
const lanes = WAVE.lanes

function promptFor(slug) {
  return `You are implementing ONE cross-cutting cleanup requirement in the Apache Hadoop source tree at /workspace.

REQUIREMENT SLUG: ${slug}
REQUIREMENT FILE: /workspace/requirements/${slug}.yaml   <-- READ THIS FIRST

The \`title:\` names the real upstream Apache Hadoop JIRA. These particular requirements are BROAD, MECHANICAL sweeps that can touch dozens or hundreds of files. Work like an engineer doing a refactor, not like someone editing one file:

  1. First, measure the blast radius with grep, e.g.
       grep -rl 'com.google.common.base.Preconditions' <module> --include=*.java | wc -l
     and understand the exact transformation the upstream commit performed.
  2. Prefer a SCRIPTED transformation (a small python3 script or sed run from Bash) over hundreds of manual edits, then spot-check a representative sample of the results by reading the files.
  3. After the sweep, re-grep to prove there are no leftovers in the scope you were asked to cover (and no accidental hits outside that scope).
  4. Beware of the traps:
       - \`Preconditions.checkNotNull(x, "msg")\` / \`checkArgument\` / \`checkState\` semantics and message formatting ('%s' guava-style vs Java): org.apache.hadoop.util.Preconditions exists in this tree - read it first and keep exception TYPES and MESSAGES identical.
       - Do not touch generated sources, \`target/\` directories, third-party shaded code, or files under hadoop-tools/hadoop-aws/src/test resources you do not understand.
       - Removing an import that is still used breaks the build; adding an unused one is also a (checkstyle) failure. Verify per file.
       - Static imports and fully-qualified usages count too.
  5. You MAY verify compilation of a module you changed - it is fast and offline:
       cd /workspace && mvn -o -B -q -DskipTests -Denforcer.skip=true -Dcheckstyle.skip=true -pl <module/path> compile
     (add \`test-compile\` if you changed test sources). Only build the modules you actually touched, never the whole reactor, and never run two maven builds at once - take the lock: \`flock /tmp/hadoop-mvn.lock mvn -o ...\`.

Scope discipline: implement ONLY this requirement. Other agents are working in this same tree.

FORBIDDEN: git checkout/switch/stash/reset/revert/clean/rebase/merge/cherry-pick, \`git add\` without an explicit pathspec, \`git commit --amend\`, deleting files you did not create.

WHEN COMPLETE, commit it yourself (list every changed path; for very large sweeps you may use directory pathspecs, e.g. \`hadoop-common-project/hadoop-common/src/main/java\`, as long as they cover only YOUR changes):

  cd /workspace && flock /tmp/hadoop-git.lock bash -c 'git add -A -- PATH1 PATH2 ... && git diff --cached --binary > requirement_patches/${slug}.diff && git commit -q -m "impl: ${slug}" && git log --oneline -1 && wc -c requirement_patches/${slug}.diff'

requirement_patches/${slug}.diff MUST be non-empty afterwards.

Return ONLY this JSON:
{"slug":"${slug}","status":"done"|"partial"|"blocked","files_changed":<int>,"committed":true|false,"summary":"<=3 sentences","notes":"anything the orchestrator must know"}`
}

const SCHEMA = {
  type: 'object',
  properties: {
    slug: { type: 'string' },
    status: { type: 'string' },
    files_changed: { type: 'number' },
    committed: { type: 'boolean' },
    summary: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['slug', 'status', 'committed', 'summary'],
  additionalProperties: true,
}

phase('Sweep')
log(`${lanes.length} lanes, ${lanes.reduce((a, l) => a + l.length, 0)} sweep requirements`)

const results = await parallel(lanes.map((lane) => async () => {
  const out = []
  for (const slug of lane) {
    let r = null
    try {
      r = await agent(promptFor(slug), { label: slug, phase: 'Sweep', schema: SCHEMA })
    } catch (e) {
      r = { slug, status: 'blocked', committed: false, summary: `agent error: ${String(e).slice(0, 200)}` }
    }
    out.push(r || { slug, status: 'blocked', committed: false, summary: 'agent returned null' })
  }
  return out
}))

const flat = results.filter(Boolean).flat().filter(Boolean)
return {
  total: flat.length,
  done: flat.filter((r) => r.status === 'done').length,
  committed: flat.filter((r) => r.committed).length,
  problems: flat.filter((r) => r.status !== 'done' || !r.committed),
}

