{"slug":"${slug}","status":"done"|"partial"|"blocked","files_changed":<int>,"committed":true|false,"summary":"<=3 sentences","notes":"anything the orchestrator must know"}`
}

const SCHEMA = {
  type: 'object',
  properties: {
    slug: { type: 'string' },
    status: { type: 'string' },
    files_changed: { type: 'number' },
    committed: { type: 'boolean' },
    summary: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['slug', 'status', 'committed', 'summary'],
  additionalProperties: true,
}

phase('Sweep')
log(`${lanes.length} lanes, ${lanes.reduce((a, l) => a + l.length, 0)} sweep requirements`)

const results = await parallel(lanes.map((lane) => async () => {
  const out = []
  for (const slug of lane) {
    let r = null
    try {
      r = await agent(promptFor(slug), { label: slug, phase: 'Sweep', schema: SCHEMA })
    } catch (e) {
      r = { slug, status: 'blocked', committed: false, summary: `agent error: ${String(e).slice(0, 200)}` }
    }
    out.push(r || { slug, status: 'blocked', committed: false, summary: 'agent returned null' })
  }
  return out
}))

const flat = results.filter(Boolean).flat().filter(Boolean)
return {
  total: flat.length,
  done: flat.filter((r) => r.status === 'done').length,
  committed: flat.filter((r) => r.committed).length,
  problems: flat.filter((r) => r.status !== 'done' || !r.committed),
}

