#!/usr/bin/env python3
"""Generate wave workflow scripts.

  build_wave.py impl A B      -> implementation waves for lane groups A/B (skips done slugs)
  build_wave.py sweep C       -> sweep wave for the broad cleanup lanes
  build_wave.py verify N      -> N shards of the verify wave over every slug that has a patch
"""
import json, os, sys

BASE = '/workspace/agent_plans'
SPEC = json.load(open(f'{BASE}/lanes.json'))
PATCHDIR = '/workspace/requirement_patches'

GROUPS = {
    'A': lambda n: n.startswith(('HDFS_', 'RBF_', 'LIBHDFS', 'NATIVE_', 'COMMON_')),
    'B': lambda n: n.startswith(('YARN_', 'MR', 'S3A', 'ABFS', 'OSS', 'DISTCP', 'DOCS', 'CI_DEV', 'POM')),
    'C': lambda n: n.startswith(('GUAVA_', 'SWEEP_', 'ENFORCER')),
}


def done(slug):
    p = os.path.join(PATCHDIR, slug + '.diff')
    return os.path.exists(p) and os.path.getsize(p) > 0


def emit(path, template, wave):
    js = open(f'{BASE}/{template}').read().replace('/*__WAVE__*/', json.dumps(wave))
    open(path, 'w').write(js)
    print(f'{path}: {len(wave["lanes"])} lanes, {sum(len(l) for l in wave["lanes"])} items')


def impl(groups):
    for g in groups:
        lanes = []
        for name, slugs in SPEC['lanes'].items():
            if not GROUPS[g](name):
                continue
            rem = [s for s in slugs if not done(s)]
            if rem:
                lanes.append(rem)
        if lanes:
            emit(f'{BASE}/wave_{g}.js', 'impl_wave_template.js',
                 {'lanes': lanes, 'light': SPEC['light']})


def sweep(groups):
    for g in groups:
        lanes = []
        for name, slugs in SPEC['lanes'].items():
            if not GROUPS[g](name):
                continue
            rem = [s for s in slugs if not done(s)]
            if rem:
                lanes.append(rem)
        if lanes:
            emit(f'{BASE}/sweep_{g}.js', 'sweep_wave_template.js', {'lanes': lanes})


def verify(nshards):
    # keep lane grouping (same-file requirements stay serialized), spread lanes over shards
    lanes = []
    for name, slugs in SPEC['lanes'].items():
        have = [s for s in slugs if done(s)]
        if have:
            lanes.append(have)
    lanes.sort(key=len, reverse=True)
    shards = [[] for _ in range(nshards)]
    for i, lane in enumerate(lanes):
        shards[i % nshards].append(lane)
    for i, sh in enumerate(shards):
        if sh:
            emit(f'{BASE}/verify_{i}.js', 'verify_wave_template.js', {'lanes': sh})


if __name__ == '__main__':
    mode = sys.argv[1]
    if mode == 'impl':
        impl(sys.argv[2:] or ['A', 'B'])
    elif mode == 'sweep':
        sweep(sys.argv[2:] or ['C'])
    elif mode == 'verify':
        verify(int(sys.argv[2]) if len(sys.argv) > 2 else 4)
    else:
        raise SystemExit('unknown mode')

