#!/usr/bin/env python3
"""Run a full offline reactor build and summarise compile failures per module.

Usage: python3 agent_plans/compile_gate.py [logfile]
Writes /tmp/compile_report.json and prints a summary.
"""
import json, re, subprocess, sys, os

LOG = sys.argv[1] if len(sys.argv) > 1 else '/tmp/mvn-gate.log'

CMD = ['flock', '/tmp/hadoop-mvn.lock',
       'mvn', '-o', '-B', '-DskipTests', '-fae',
       '-Dmaven.javadoc.skip=true', '-Denforcer.skip=true', '-Dcheckstyle.skip=true',
       '-Dspotbugs.skip=true', '-Dpmd.skip=true', '-Drat.skip=true', 'install']


def run():
    with open(LOG, 'w') as fh:
        subprocess.run(CMD, cwd='/workspace', stdout=fh, stderr=subprocess.STDOUT)


def parse():
    text = open(LOG, errors='replace').read().splitlines()
    modules = {}
    cur = None
    errors = []
    for line in text:
        m = re.match(r'\[ERROR\] Failed to execute goal .* on project ([\w.-]+): (.*)', line)
        if m:
            cur = m.group(1)
            modules.setdefault(cur, [])
        m2 = re.match(r'\[ERROR\] (/workspace/[^:]+\.java):\[(\d+),(\d+)\] (.*)', line)
        if m2:
            errors.append({'file': m2.group(1).replace('/workspace/', ''),
                           'line': int(m2.group(2)), 'msg': m2.group(4)})
    summary = {}
    for line in text:
        m = re.match(r'\[INFO\] (.*?) \.+ (SUCCESS|FAILURE|SKIPPED)', line)
        if m:
            summary[m.group(1).strip()] = m.group(2)
    byfile = {}
    for e in errors:
        byfile.setdefault(e['file'], []).append(f"L{e['line']}: {e['msg']}")
    report = {
        'failed_modules': sorted(modules),
        'skipped': [k for k, v in summary.items() if v == 'SKIPPED'],
        'failure_modules_named': [k for k, v in summary.items() if v == 'FAILURE'],
        'error_files': byfile,
        'error_count': len(errors),
    }
    json.dump(report, open('/tmp/compile_report.json', 'w'), indent=1)
    print(json.dumps({k: (v if k != 'error_files' else {f: len(x) for f, x in v.items()})
                      for k, v in report.items()}, indent=1)[:4000])


if __name__ == '__main__':
    if '--parse-only' not in sys.argv:
        run()
    parse()

